<script>
(function() {
    // ---------- HERO COIN: 3D canvas with raking specular, reeded edge, two faces ----------
    const heroCanvas = document.getElementById('coin-hero');
    const ctx = heroCanvas.getContext('2d');
    const W = 400, H = 400;
    heroCanvas.width = W; heroCanvas.height = H;

    // deterministic pseudo-random for consistent noise (embossing)
    function seededRandom(seed) {
        return function() {
            seed = (seed * 1664525 + 1013904223) & 0xffffffff;
            return (seed >>> 0) / 4294967296;
        };
    }
    const rng = seededRandom(20250315);

    // precompute emboss height map (front emblem + back text)
    const embossSize = 128;
    const embossFront = new Float32Array(embossSize * embossSize);
    const embossBack = new Float32Array(embossSize * embossSize);
    // front: emblem circle + "WT" stylized
    for (let y = 0; y < embossSize; y++) {
        for (let x = 0; x < embossSize; x++) {
            const cx = x - embossSize/2, cy = y - embossSize/2;
            const dist = Math.sqrt(cx*cx + cy*cy) / (embossSize/2);
            let val = 0;
            // central emblem
            if (dist < 0.7) {
                const angle = Math.atan2(cy, cx);
                // raised ring
                const ring = Math.sin(dist * 12) * 0.15 + 0.5;
                // stylized W
                const w = (Math.abs(cx) < 12 && Math.abs(cy) < 20) ? 0.6 : 0;
                const t = (Math.abs(cy) < 8 && Math.abs(cx) < 25) ? 0.4 : 0;
                val = Math.max(ring * 0.5, w, t);
                // add noise for relief
                val += (rng() - 0.5) * 0.15;
                val = Math.min(1, Math.max(0, val));
            } else if (dist < 0.95) {
                val = 0.1 + (rng() - 0.5) * 0.1;
            } else {
                val = 0;
            }
            embossFront[y * embossSize + x] = val;
        }
    }
    // back: denomination text "10,000 TOKENS" as emboss
    for (let y = 0; y < embossSize; y++) {
        for (let x = 0; x < embossSize; x++) {
            const cx = x - embossSize/2, cy = y - embossSize/2;
            const dist = Math.sqrt(cx*cx + cy*cy) / (embossSize/2);
            let val = 0;
            if (dist < 0.75) {
                // simulate text lines
                const row = Math.floor((cy + 20) / 14);
                if (row === 2 || row === 3) {
                    const col = Math.floor((cx + 40) / 9);
                    if (col >= 0 && col < 9) val = 0.7;
                }
                val += (rng() - 0.5) * 0.1;
                val = Math.min(1, Math.max(0.05, val));
            } else if (dist < 0.95) {
                val = 0.1;
            } else {
                val = 0;
            }
            embossBack[y * embossSize + x] = val;
        }
    }

    // metallic material: base color, specular exponent
    const goldBase = [0.85, 0.65, 0.25];
    const goldSpec = [1.0, 0.85, 0.4];
    const shininess = 80;

    // render coin at normalized time t in [0,1]
    function renderCoin(t) {
        ctx.clearRect(0, 0, W, H);
        // background: subtle vignette
        const grad = ctx.createRadialGradient(200, 200, 50, 200, 200, 280);
        grad.addColorStop(0, '#1e1b22');
        grad.addColorStop(1, '#0b0a0c');
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, W, H);

        // coin parameters
        const radius = 150;
        const cx = 200, cy = 200;
        // rotation angles: yaw (vertical axis) and pitch (horizontal flip)
        const yaw = t * Math.PI * 2;          // full rotation
        const pitch = Math.sin(t * Math.PI * 2) * 0.6; // flip both faces visible
        // face: front if cos(yaw) > 0 else back (with smooth transition)
        const faceMix = (Math.cos(yaw) + 1) / 2; // 0..1, 0 = back, 1 = front

        // light direction (world space) – fixed, but specular highlight rakes due to rotation
        const lightDir = [0.3, -0.5, 0.8];
        const lightLen = Math.sqrt(lightDir[0]*lightDir[0]+lightDir[1]*lightDir[1]+lightDir[2]*lightDir[2]);
        const L = [lightDir[0]/lightLen, lightDir[1]/lightLen, lightDir[2]/lightLen];

        // draw coin as disc with per-pixel normal from emboss + rotation
        const imageData = ctx.createImageData(W, H);
        const data = imageData.data;

        for (let py = 0; py < H; py++) {
            for (let px = 0; px < W; px++) {
                const dx = px - cx, dy = py - cy;
                const dist = Math.sqrt(dx*dx + dy*dy);
                if (dist > radius + 1) continue; // background

                // map to normalized coin coordinates [-1,1]
                const nx = dx / radius, ny = dy / radius;
                const r2 = nx*nx + ny*ny;
                if (r2 > 1.0) {
                    // reeded edge: thin ring
                    if (dist > radius - 4 && dist <= radius + 1) {
                        const idx = (py * W + px) * 4;
                        const ridge = Math.sin(px * 0.5 + py * 0.3) * 0.5 + 0.5;
                        const base = 0.3 + ridge * 0.2;
                        data[idx] = 120 + ridge * 40;
                        data[idx+1] = 90 + ridge * 30;
                        data[idx+2] = 50 + ridge * 20;
                        data[idx+3] = 255;
                    }
                    continue;
                }

                // sample emboss from front/back
                const u = Math.floor((nx * 0.5 + 0.5) * (embossSize-1));
                const v = Math.floor((ny * 0.5 + 0.5) * (embossSize-1));
                const clampedU = Math.min(embossSize-1, Math.max(0, u));
                const clampedV = Math.min(embossSize-1, Math.max(0, v));
                const hFront = embossFront[clampedV * embossSize + clampedU];
                const hBack = embossBack[clampedV * embossSize + clampedU];
                const height = faceMix * hFront + (1 - faceMix) * hBack;

                // normal from height gradient (central differences)
                const du = 1/embossSize;
                const dv = 1/embossSize;
                const u1 = Math.min(embossSize-1, Math.max(0, clampedU+1));
                const u2 = Math.min(embossSize-1, Math.max(0, clampedU-1));
                const v1 = Math.min(embossSize-1, Math.max(0, clampedV+1));
                const v2 = Math.min(embossSize-1, Math.max(0, clampedV-1));
                const hU1 = (faceMix * embossFront[clampedV * embossSize + u1] + (1-faceMix) * embossBack[clampedV * embossSize + u1]);
                const hU2 = (faceMix * embossFront[clampedV * embossSize + u2] + (1-faceMix) * embossBack[clampedV * embossSize + u2]);
                const hV1 = (faceMix * embossFront[v1 * embossSize + clampedU] + (1-faceMix) * embossBack[v1 * embossSize + clampedU]);
                const hV2 = (faceMix * embossFront[v2 * embossSize + clampedU] + (1-faceMix) * embossBack[v2 * embossSize + clampedU]);
                let gradX = (hU1 - hU2) * 0.5;
                let gradY = (hV1 - hV2) * 0.5;
                // scale for emboss strength
                const embossStrength = 0.4;
                gradX *= embossStrength;
                gradY *= embossStrength;

                // base normal (pointing out of disc)
                let nz = Math.sqrt(1 - nx*nx - ny*ny);
                if (isNaN(nz)) nz = 0;
                // perturb normal with height gradient
                let normX = -nx + gradX;
                let normY = -ny + gradY;
                let normZ = nz + 0.2; // bias
                const len = Math.sqrt(normX*normX + normY*normY + normZ*normZ);
                if (len > 0.0001) {
                    normX /= len; normY /= len; normZ /= len;
                } else {
                    normX = 0; normY = 0; normZ = 1;
                }

                // rotate normal by yaw and pitch (world space)
                // yaw around Y
                const cosY = Math.cos(yaw), sinY = Math.sin(yaw);
                let rx = normX * cosY - normZ * sinY;
                let ry = normY;
                let rz = normX * sinY + normZ * cosY;
                // pitch around X
                const cosP = Math.cos(pitch), sinP = Math.sin(pitch);
                let fx = rx;
                let fy = ry * cosP - rz * sinP;
                let fz = ry * sinP + rz * cosP;
                const flen = Math.sqrt(fx*fx + fy*fy + fz*fz);
                if (flen > 0.0001) { fx /= flen; fy /= flen; fz /= flen; }
                else { fx=0; fy=0; fz=1; }

                // diffuse
                const diff = Math.max(0, fx*L[0] + fy*L[1] + fz*L[2]);
                // specular (Blinn-Phong)
                const Hx = L[0], Hy = L[1], Hz = L[2] + 1; // half vector approx
                const hlen = Math.sqrt(Hx*Hx + Hy*Hy + Hz*Hz);
                const hx = Hx/hlen, hy = Hy/hlen, hz = Hz/hlen;
                const ndoth = Math.max(0, fx*hx + fy*hy + fz*hz);
                const spec = Math.pow(ndoth, shininess) * 0.8;

                // base color: mix front/back tint
                const frontTint = [0.92, 0.78, 0.35];
                const backTint = [0.7, 0.75, 0.8];
                const baseR = faceMix * frontTint[0] + (1-faceMix) * backTint[0];
                const baseG = faceMix * frontTint[1] + (1-faceMix) * backTint[1];
                const baseB = faceMix * frontTint[2] + (1-faceMix) * backTint[2];

                const ambient = 0.25;
                let r = baseR * (ambient + diff * 0.7) + spec * 0.9;
                let g = baseG * (ambient + diff * 0.7) + spec * 0.7;
                let b = baseB * (ambient + diff * 0.7) + spec * 0.5;
                // clamp
                r = Math.min(255, Math.max(0, r * 255));
                g = Math.min(255, Math.max(0, g * 255));
                b = Math.min(255, Math.max(0, b * 255));

                const idx = (py * W + px) * 4;
                data[idx] = r;
                data[idx+1] = g;
                data[idx+2] = b;
                data[idx+3] = 255;
            }
        }
        ctx.putImageData(imageData, 0, 0);

        // reeded edge overlay (circular ridges)
        ctx.save();
        ctx.beginPath();
        ctx.arc(cx, cy, radius-2, 0, Math.PI*2);
        ctx.clip();
        for (let a = 0; a < Math.PI*2; a += 0.03) {
            const r1 = radius - 6 + Math.sin(a * 20) * 2;
            const x1 = cx + Math.cos(a) * r1;
            const y1 = cy + Math.sin(a) * r1;
            ctx.fillStyle = 'rgba(180,140,70,0.15)';
            ctx.beginPath();
            ctx.arc(x1, y1, 1.5, 0, Math.PI*2);
            ctx.fill();
        }
        ctx.restore();
    }

    // animation loop
    let animId = null;
    let running = true;
    let time = 0;

    function animate() {
        if (!running) return;
        time = (time + 0.005) % 1.0;
        renderCoin(time);
        animId = requestAnimationFrame(animate);
    }

    // public API
    window.demo = {
        canvas: heroCanvas,
        setTime: function(t) {
            const val = Math.min(1, Math.max(0, t));
            renderCoin(val);
        },
        pause: function() {
            running = false;
            if (animId) {
                cancelAnimationFrame(animId);
                animId = null;
            }
        }
    };

    // start animation
    animate();

    // ---------- EDITION COINS (procedural 2D canvas, metallic) ----------
    function renderEditionCoin(canvas, baseColor, specColor, label, soldOut, comingSoon) {
        const c = canvas.getContext('2d');
        const w = canvas.width, h = canvas.height;
        c.clearRect(0, 0, w, h);
        // background
        c.fillStyle = '#0f0e12';
        c.fillRect(0, 0, w, h);

        const cx = w/2, cy = h/2, r = 60;
        // metallic gradient
        const grad = c.createRadialGradient(cx-15, cy-15, 5, cx, cy, r);
        const col1 = baseColor.slice();
        const col2 = [baseColor[0]*0.5, baseColor[1]*0.5, baseColor[2]*0.5];
        grad.addColorStop(0, `rgb(${col1[0]*255},${col1[1]*255},${col1[2]*255})`);
        grad.addColorStop(0.6, `rgb(${col1[0]*200},${col1[1]*200},${col1[2]*200})`);
        grad.addColorStop(1, `rgb(${col2[0]*255},${col2[1]*255},${col2[2]*255})`);
        c.beginPath();
        c.arc(cx, cy, r, 0, Math.PI*2);
        c.fillStyle = grad;
        c.fill();

        // specular highlight
        const specGrad = c.createRadialGradient(cx-20, cy-20, 5, cx-20, cy-20, 40);
        specGrad.addColorStop(0, `rgba(255,255,240,0.5)`);
        specGrad.addColorStop(1, `rgba(255,255,240,0)`);
        c.beginPath();
        c.arc(cx, cy, r, 0, Math.PI*2);
        c.fillStyle = specGrad;
        c.fill();

        // edge reeding
        for (let a = 0; a < Math.PI*2; a += 0.08) {
            const x = cx + Math.cos(a) * (r-3);
            const y = cy + Math.sin(a) * (r-3);
            c.fillStyle = 'rgba(0,0,0,0.2)';
            c.beginPath();
            c.arc(x, y, 2, 0, Math.PI*2);
            c.fill();
        }

        // embossed text / emblem
        c.fillStyle = `rgba(255,255,220,0.25)`;
        c.font = 'bold 14px monospace';
        c.textAlign = 'center';
        c.textBaseline = 'middle';
        c.fillText(label, cx, cy-6);
        if (soldOut) {
            c.fillStyle = '#b55a3a';
            c.font = 'bold 10px sans-serif';
            c.fillText('SOLD OUT', cx, cy+18);
        } else if (comingSoon) {
            c.fillStyle = '#7aaec4';
            c.font = '9px sans-serif';
            c.fillText('spring 2025', cx, cy+18);
        } else {
            c.fillStyle = '#d4c9a8';
            c.font = '9px sans-serif';
            c.fillText('● available', cx, cy+18);
        }
    }

    // render each edition
    const editions = [
        { canvas: document.querySelector('[data-edition="bronze"] .edition-canvas'), base: [0.72, 0.45, 0.2], label: 'BRONZE' },
        { canvas: document.querySelector('[data-edition="silver"] .edition-canvas'), base: [0.75, 0.75, 0.8], label: 'SILVER' },
        { canvas: document.querySelector('[data-edition="gold"] .edition-canvas'), base: [0.85, 0.65, 0.2], label: 'GOLD', soldOut: true },
        { canvas: document.querySelector('[data-edition="black"] .edition-canvas'), base: [0.15, 0.15, 0.18], label: 'OBSIDIAN', comingSoon: true }
    ];
    editions.forEach(e => {
        if (e.canvas) renderEditionCoin(e.canvas, e.base, null, e.label, e.soldOut, e.comingSoon);
    });
})();
